/**
 * The dictionary for «Балда».
 *
 * The plan is explicit that a word must not be "checked" by a regular expression or by whether
 * a page exists in a search engine. What it needs is a fixed list of nouns in an agreed form,
 * carried with the game so that two players on two devices agree on what counts as a word.
 *
 * **The word list is not written here, and is not in this module's chunk.** It is generated by
 * `scripts/build-dictionary.mjs` from the MIT-licensed Russian-Nouns list into `words.data.ts`
 * (~965 KB) with its metadata in `words.meta.ts` (1 KB). This module is the synchronous facade the
 * engine needs, and `loadDictionary()` is how the weight is paid for: the panel calls it while
 * showing a loading state, and everything else here works on whatever has loaded so far.
 *
 * The synchronous facade matters. The engine walks board paths and asks "is this a word" thousands of
 * times inside one event; making that async would turn a few milliseconds into thousands of
 * microtask hops, so the decision is: load once, explicitly, then stay synchronous.
 *
 * A previous version of this file held 3,713 words picked by hand with no recorded origin:
 * unauditable, and unfair in a quiet way, because a word missing from a hand list is
 * indistinguishable to a player from a word that is not Russian.
 *
 * Limits of the list, stated rather than hidden: it is not exhaustive, some rare nouns are missing,
 * and a word absent here is refused even if it is real Russian. The version number is part of the
 * game: a saved game keeps the dictionary it was started with.
 */

import {
  WORDS_ALPHABET,
  WORDS_CHECKSUM,
  WORDS_LICENSED_COUNT,
  WORDS_SUPPLEMENT_COUNT,
  WORDS_TOTAL_COUNT,
  WORDS_VERSION,
} from "./words.meta";

/** Which list this is. Bumped whenever the word set changes, so saved games do not mix lists. */
export const DICTIONARY_VERSION = WORDS_VERSION;

/** Letters a word may contain after normalisation. Taken from the generated list. */
export const ALPHABET = WORDS_ALPHABET;

/**
 * Normalises a word the way the whole game will: lowercase, ё folded to е.
 *
 * The fold is done on input, on the board and in the index, so there is no path where "ёлка"
 * and "елка" are different words. The plan asks for exactly this and calls out that it must be
 * uniform - a normalisation applied in one place only is a bug that shows up once per game.
 */
export function normalise(word: string): string {
  return word.trim().toLocaleLowerCase("ru-RU").replace(/ё/g, "е");
}

/**
 * Letters that may not begin a Russian word.
 *
 * The generated list is filtered for this already; the check stays because it is cheap, it documents
 * the rule where the rule is enforced, and a future change to the generator must not be able to
 * silently let a board row score with a "word" Russian cannot start.
 */
const NO_LEADING = new Set(["ь", "ъ", "ы"]);

const VOWELS = new Set("аеиоуыэюя".split(""));

/** Every allowed word, normalised, as a Set for constant-time lookup. Null until loaded. */
let wordSet: Set<string> | null = null;

/** The in-flight or finished load, so concurrent callers share one download. */
let loading: Promise<void> | null = null;

/**
 * Whether the words are in memory. Everything else in this module is written to be safe before
 * this is true - it simply recognises no words, rather than throwing.
 */
export function dictionaryLoaded(): boolean {
  return wordSet !== null;
}

/**
 * Downloads and indexes the word list. Safe to call repeatedly; the work happens once.
 *
 * Returns a promise so the panel can show a loading state and a retry button, as the plan requires:
 * if the dictionary cannot be loaded, the game must say so rather than start accepting any word.
 */
export function loadDictionary(): Promise<void> {
  if (wordSet) return Promise.resolve();
  if (!loading) {
    loading = import("./words.data")
      .then((module) => {
        const parsed: string[] = module.WORDS.split(/\s+/)
          .map((word) => word.trim())
          .filter((word) => word.length > 0)
          .map((word) => normalise(word));
        wordSet = new Set(parsed);
      })
      .catch((error: unknown) => {
        // Forget the rejected promise so a retry can try again rather than replay the failure.
        loading = null;
        throw error;
      });
  }
  return loading;
}

export function dictionary(): Set<string> {
  return wordSet ?? new Set<string>();
}

export function isWord(word: string): boolean {
  const normalised = normalise(word);
  if (!wordSet || !wordSet.has(normalised)) return false;
  if (NO_LEADING.has(normalised[0])) return false;
  // A word made only of consonants is not a word in Russian either.
  return [...normalised].some((letter) => VOWELS.has(letter));
}

/**
 * How many words the game recognises, or how many it will once loaded.
 *
 * Reads the generated total before loading so the rules screen can state the size without paying for
 * the words, and the real count afterwards. `dictionaryLoaded()` is how a caller tells which it got.
 */
export function dictionarySize(): number {
  return wordSet ? wordSet.size : WORDS_TOTAL_COUNT;
}

/** How the total splits between the licensed source and the words added on top of it. */
export function dictionaryBreakdown(): { licensed: number; supplement: number; total: number } {
  return { licensed: WORDS_LICENSED_COUNT, supplement: WORDS_SUPPLEMENT_COUNT, total: WORDS_TOTAL_COUNT };
}

/**
 * What the dictionary is, for the rules screen and for a networked game's pre-flight check.
 *
 * Two clients must agree on version and checksum before a game starts; otherwise one could accept a
 * word the other refuses, and the disagreement would look to the players like cheating.
 */
export function dictionaryMeta(): { version: number; checksum: string; size: number } {
  return { version: WORDS_VERSION, checksum: WORDS_CHECKSUM, size: WORDS_TOTAL_COUNT };
}

/**
 * Whether the dictionary loaded at all.
 *
 * The plan is explicit: if the dictionary cannot be loaded, show a retry rather than start
 * accepting any word. This is the check the interface uses.
 */
export function dictionaryReady(): boolean {
  return dictionarySize() >= 1000;
}

/**
 * Every prefix of every word, so a search can stop as soon as the letters cannot spell anything.
 *
 * This is the difference between a usable game and a frozen tab. Walking every simple path on
 * a 5x5 board is thousands of paths per square, and doing that for 33 possible letters froze
 * the browser for minutes. With prefixes, a path dies the moment "абв" cannot start a word,
 * and the whole board is searched in a few milliseconds.
 *
 * Built on first use after loading rather than during load: the index is only needed once a human or
 * a bot starts searching, and building it eagerly would add to the time the panel spends loading.
 */
let prefixSet: Set<string> | null = null;

export function prefixes(): Set<string> {
  if (!prefixSet) {
    prefixSet = new Set();
    for (const word of dictionary()) {
      for (let length = 1; length <= word.length; length += 1) {
        prefixSet.add(word.slice(0, length));
      }
    }
  }
  return prefixSet;
}

/** Whether more letters could still make this prefix into a word. */
export function isPrefix(text: string): boolean {
  return prefixes().has(text);
}

/** For tests and the rules screen: the list as an array. Empty until loaded. */
export function allWords(): string[] {
  return [...dictionary()].sort();
}
